import SwiftUI

@main
struct DriverApp: App {
    var body: some Scene {
        WindowGroup {
            Text("Driver")
        }
    }
}

import XCTest

final class ElementDriverTests: XCTestCase {

    func dump(_ name: String, _ app: XCUIApplication) {
        let desc = app.debugDescription
        let url = URL(fileURLWithPath: "/tmp/" + name)
        try? desc.write(to: url, atomically: true, encoding: .utf8)
    }

    func testOpenTeamStandupAndInvite() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        Thread.sleep(forTimeInterval: 2.0)
        dump("hier_home.txt", app)

        let teamStandup = app.staticTexts["Team Standup"].firstMatch
        XCTAssertTrue(teamStandup.waitForExistence(timeout: 15), "Team Standup not found")
        teamStandup.tap()
        Thread.sleep(forTimeInterval: 2.5)
        dump("hier_room.txt", app)

        // Open room details by tapping the room title in the navigation bar
        let navTitle = app.navigationBars.buttons["Team Standup"].firstMatch
        if navTitle.waitForExistence(timeout: 10) {
            navTitle.tap()
        } else {
            // fallback: any static text title in nav bar
            app.navigationBars.staticTexts["Team Standup"].firstMatch.tap()
        }
        Thread.sleep(forTimeInterval: 2.5)
        dump("hier_details.txt", app)

        // Try to open invite / add people
        let candidates = ["Invite", "Add people", "Invite people", "Add members", "Invite to room"]
        var tapped = false
        for label in candidates {
            let b = app.buttons[label].firstMatch
            if b.waitForExistence(timeout: 2) {
                b.tap()
                tapped = true
                break
            }
        }
        if !tapped {
            // try table cells / static texts
            for label in candidates {
                let c = app.cells.staticTexts[label].firstMatch
                if c.waitForExistence(timeout: 2) {
                    c.tap()
                    tapped = true
                    break
                }
            }
        }
        Thread.sleep(forTimeInterval: 2.5)
        dump("hier_invite.txt", app)
    }
}

import XCTest

final class ElementDriverTests: XCTestCase {

    func dump(_ name: String, _ app: XCUIApplication) {
        let desc = app.debugDescription
        let url = URL(fileURLWithPath: "/tmp/" + name)
        try? desc.write(to: url, atomically: true, encoding: .utf8)
    }

    func dismissModal(_ app: XCUIApplication) {
        let gotIt = app.buttons["Got it"].firstMatch
        if gotIt.waitForExistence(timeout: 3) {
            gotIt.tap()
            Thread.sleep(forTimeInterval: 1.0)
        }
    }

    func testOpenTeamStandupAndInvite() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        Thread.sleep(forTimeInterval: 2.0)
        dismissModal(app)

        let addPeople = app.buttons["Add people"].firstMatch
        if !addPeople.exists {
            let room = app.staticTexts["Team Standup"].firstMatch
            XCTAssertTrue(room.waitForExistence(timeout: 10), "Team Standup room not found")
            room.tap()
            Thread.sleep(forTimeInterval: 2.5)
            dismissModal(app)
        }

        let ap = app.buttons["Add people"].firstMatch
        XCTAssertTrue(ap.waitForExistence(timeout: 10), "Add people button not found")
        ap.tap()
        Thread.sleep(forTimeInterval: 2.5)
        dump("hier_invite.txt", app)
    }
}

